//! Parity of acquisition functions with BoTorch (fixtures in
//! `tests/fixtures/phase2/acqf_*.json`, generated by
//! `scripts/generate_fixtures.py --phase 2`).
//!
//! * analytic acquisition values and autograd gradients at test points;
//! * MC acquisition values and gradients with BoTorch's explicit base samples
//!   (q = 1, 2, 3, with and without pending points);
//! * qLogNoisyExpectedImprovement (incremental or not, full or pruned
//!   baseline), including BoTorch's default `cache_root=True` evaluated with
//!   its effective base samples;
//! * `prune_inferior_points` with explicit base samples.
//!
//! Values in log space (LogEI, LogPI, qLogEI, qLogNEI) are compared by
//! `|a - e| / max(|e|, 1)`, other values by their relative error, gradients
//! by the mixed elementwise/normwise relative error of `common::rel_err`.
//! The LogEI gradient of BoTorch (autograd through `_log_ei_helper`) has a
//! relative error of about `ε u²` for a scaled improvement `u ≪ -1` (1.5e-10
//! at `u = -10³`), whereas botorch_core's is accurate to machine precision
//! (checked against mpmath in the unit tests); LogEI gradient errors are
//! therefore reported relative to the bound `1e-10 + 4 ε u²`, i.e. as
//! `err · 1e-10 / (1e-10 + 4 ε u²)`.
//! Run with `--nocapture` to print the error tables.

mod common;

use std::path::PathBuf;
use std::sync::Arc;

use botorch_core::acquisition::{
    prune_inferior_points_indices, AcquisitionFunction, ExpectedImprovement,
    LogExpectedImprovement, LogProbabilityOfImprovement, McAcquisitionOptions, PosteriorMean,
    PosteriorStandardDeviation, ProbabilityOfImprovement, PruneOptions, QExpectedImprovement,
    QLogExpectedImprovement, QLogExpectedImprovementOptions, QLogNoisyExpectedImprovement,
    QLogNoisyExpectedImprovementOptions, QProbabilityOfImprovement, QSimpleRegret,
    QUpperConfidenceBound, UpperConfidenceBound,
};
use botorch_core::sampling::SobolQMCNormalSampler;
use botorch_core::{Matrix, Model};
use common::*;
use serde::Deserialize;

/// Tolerance for values and gradients.
const RTOL: f64 = 1e-10;

/// Absolute agreement threshold for MC gradient entries (as in the phase-1
/// parity tests): a gradient can be a tiny result of cancellation between
/// O(1) posterior derivatives (e.g. at a far-away point that never wins the
/// `max`), where only absolute agreement at the level of machine precision is
/// meaningful.
const GRAD_ATOL: f64 = 1e-14;

#[derive(Debug, Deserialize)]
struct AnalyticCase {
    acqf: String,
    best_f: Option<f64>,
    beta: Option<f64>,
    maximize: bool,
    values: Vec<f64>,
    grads: Vec<Vec<f64>>,
}

#[derive(Debug, Deserialize)]
struct McResult {
    acqf: String,
    best_f: Option<f64>,
    beta: Option<f64>,
    fat: Option<bool>,
    tau: Option<f64>,
    value: f64,
    grad: Vec<Vec<f64>>,
}

#[derive(Debug, Deserialize)]
struct McCase {
    q: usize,
    x: Vec<Vec<f64>>,
    x_pending: Option<Vec<Vec<f64>>>,
    base_samples: Vec<Vec<f64>>,
    results: Vec<McResult>,
}

#[derive(Debug, Deserialize)]
struct PruneCase {
    x: Vec<Vec<f64>>,
    base_samples: Vec<Vec<f64>>,
    indices: Vec<usize>,
}

#[derive(Debug, Deserialize)]
struct PruneBaseline {
    base_samples: Vec<Vec<f64>>,
    indices: Vec<usize>,
}

#[derive(Debug, Deserialize)]
struct NeiCase {
    q: usize,
    x: Vec<Vec<f64>>,
    x_pending: Option<Vec<Vec<f64>>>,
    incremental: bool,
    baseline: String,
    base_samples: Vec<Vec<f64>>,
    value: f64,
    grad: Vec<Vec<f64>>,
}

#[derive(Debug, Deserialize)]
struct NeiCacheRoot {
    x: Vec<Vec<f64>>,
    base_samples: Vec<Vec<f64>>,
    value_cache_root: f64,
    grad_cache_root: Vec<Vec<f64>>,
    value_plain: f64,
}

#[derive(Debug, Deserialize)]
struct AcqfFixture {
    name: String,
    config: Config,
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    train_yvar: Option<Vec<Vec<f64>>>,
    raw_params: Vec<f64>,
    test_x: Vec<Vec<f64>>,
    analytic: Vec<AnalyticCase>,
    mc: Vec<McCase>,
    prune: PruneCase,
    prune_baseline: PruneBaseline,
    nei: Vec<NeiCase>,
    nei_cache_root: NeiCacheRoot,
}

fn load() -> Vec<AcqfFixture> {
    let dir: PathBuf = fixture_dir().join("phase2");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("phase-2 fixture directory exists")
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.starts_with("acqf_") && n.ends_with(".json"))
        })
        .collect();
    paths.sort();
    assert!(!paths.is_empty(), "no acquisition fixtures found");
    paths
        .iter()
        .map(|p| serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap())
        .collect()
}

fn model_of(f: &AcqfFixture) -> Arc<dyn Model> {
    let mut m = build_model_from(&f.config, &f.train_x, &f.train_y, f.train_yvar.as_ref());
    m.set_raw_parameters(&f.raw_params).unwrap();
    Arc::new(m)
}

/// Relative error of a scalar (absolute if the reference is zero).
fn scalar_rel(a: f64, e: f64) -> f64 {
    if e == 0.0 {
        a.abs()
    } else {
        (a - e).abs() / e.abs()
    }
}

/// Error of a log-space scalar: absolute for |e| < 1, relative otherwise.
fn log_err(a: f64, e: f64) -> f64 {
    (a - e).abs() / e.abs().max(1.0)
}

fn sampler_from(base: &[Vec<f64>]) -> Option<Arc<SobolQMCNormalSampler>> {
    Some(Arc::new(
        SobolQMCNormalSampler::from_base_samples(matrix(base), Some(0)).unwrap(),
    ))
}

#[test]
fn parity_analytic() {
    let mut r = Report::default();
    for f in load() {
        let model = model_of(&f);
        for c in &f.analytic {
            let m = model.clone();
            let acqf: Box<dyn AcquisitionFunction> = match c.acqf.as_str() {
                "ExpectedImprovement" => {
                    Box::new(ExpectedImprovement::new(m, c.best_f.unwrap(), c.maximize).unwrap())
                }
                "LogExpectedImprovement" => {
                    Box::new(LogExpectedImprovement::new(m, c.best_f.unwrap(), c.maximize).unwrap())
                }
                "ProbabilityOfImprovement" => Box::new(
                    ProbabilityOfImprovement::new(m, c.best_f.unwrap(), c.maximize).unwrap(),
                ),
                "LogProbabilityOfImprovement" => Box::new(
                    LogProbabilityOfImprovement::new(m, c.best_f.unwrap(), c.maximize).unwrap(),
                ),
                "UpperConfidenceBound" => {
                    Box::new(UpperConfidenceBound::new(m, c.beta.unwrap(), c.maximize).unwrap())
                }
                "PosteriorMean" => Box::new(PosteriorMean::new(m, c.maximize).unwrap()),
                "PosteriorStandardDeviation" => {
                    Box::new(PosteriorStandardDeviation::new(m, c.maximize).unwrap())
                }
                other => panic!("unknown acquisition function {other}"),
            };
            let label = format!(
                "{} b={:.3e} beta={:?} max={}",
                c.acqf,
                c.best_f.unwrap_or(f64::NAN),
                c.beta,
                c.maximize
            );
            let log = acqf.is_log();
            let (mut verr, mut gerr) = (0.0f64, 0.0f64);
            let xs: Vec<Matrix> = f
                .test_x
                .iter()
                .map(|x| matrix(std::slice::from_ref(x)))
                .collect();
            let many = acqf.forward_many(&xs).unwrap();
            for (i, x) in xs.iter().enumerate() {
                let (v, g) = acqf.forward_with_grad(x).unwrap();
                let e = c.values[i];
                let err = if log { log_err(v, e) } else { scalar_rel(v, e) };
                verr = verr.max(err);
                assert_eq!(many[i], acqf.forward(x).unwrap());
                let mut err = rel_err(g.as_slice(), &c.grads[i]);
                if c.acqf == "LogExpectedImprovement" {
                    // Error bound of BoTorch's own (autograd) gradient.
                    let (m, var) = model.posterior_marginals(x).unwrap();
                    let u = (m[0] - c.best_f.unwrap()) / var[0].max(1e-12).sqrt();
                    err *= RTOL / (RTOL + 4.0 * f64::EPSILON * u * u);
                }
                gerr = gerr.max(err);
            }
            r.check(&f.name, &format!("{label} value"), verr, RTOL);
            r.check(&f.name, &format!("{label} grad"), gerr, RTOL);
        }
    }
    r.finish("analytic acquisition functions");
}

fn mc_acqf(
    model: &Arc<dyn Model>,
    c: &McResult,
    base: &[Vec<f64>],
    pending: Option<Matrix>,
) -> Box<dyn AcquisitionFunction> {
    let m = model.clone();
    let opts = McAcquisitionOptions {
        sampler: sampler_from(base),
        x_pending: pending.clone(),
        ..Default::default()
    };
    match c.acqf.as_str() {
        "qExpectedImprovement" => {
            Box::new(QExpectedImprovement::new(m, c.best_f.unwrap(), opts).unwrap())
        }
        "qLogExpectedImprovement" => Box::new(
            QLogExpectedImprovement::new(
                m,
                c.best_f.unwrap(),
                QLogExpectedImprovementOptions {
                    sampler: sampler_from(base),
                    x_pending: pending,
                    fat: c.fat.unwrap_or(true),
                    ..Default::default()
                },
            )
            .unwrap(),
        ),
        "qProbabilityOfImprovement" => Box::new(
            QProbabilityOfImprovement::new(m, c.best_f.unwrap(), c.tau.unwrap_or(1e-3), opts)
                .unwrap(),
        ),
        "qUpperConfidenceBound" => {
            Box::new(QUpperConfidenceBound::new(m, c.beta.unwrap(), opts).unwrap())
        }
        "qSimpleRegret" => Box::new(QSimpleRegret::new(m, opts).unwrap()),
        other => panic!("unknown acquisition function {other}"),
    }
}

#[test]
fn parity_monte_carlo() {
    let mut r = Report::default();
    for f in load() {
        let model = model_of(&f);
        for case in &f.mc {
            let x = matrix(&case.x);
            assert_eq!(x.nrows(), case.q);
            let pending = case.x_pending.as_ref().map(|p| matrix(p));
            for c in &case.results {
                let acqf = mc_acqf(&model, c, &case.base_samples, pending.clone());
                let (v, g) = acqf.forward_with_grad(&x).unwrap();
                let label = format!(
                    "{} q={} pending={} fat={:?} tau={:?}",
                    c.acqf,
                    case.q,
                    pending.is_some(),
                    c.fat,
                    c.tau
                );
                let verr = if acqf.is_log() {
                    log_err(v, c.value)
                } else {
                    scalar_rel(v, c.value)
                };
                r.check(&f.name, &format!("{label} value"), verr, RTOL);
                r.check_slices_atol(
                    &f.name,
                    &format!("{label} grad"),
                    &matrix_rows(&g),
                    &flatten(&c.grad),
                    RTOL,
                    GRAD_ATOL,
                );
            }
        }
    }
    r.finish("Monte-Carlo acquisition functions");
}

fn nei(
    model: &Arc<dyn Model>,
    baseline: &Matrix,
    base: &[Vec<f64>],
    pending: Option<Matrix>,
    incremental: bool,
) -> QLogNoisyExpectedImprovement {
    QLogNoisyExpectedImprovement::new(
        model.clone(),
        baseline,
        QLogNoisyExpectedImprovementOptions {
            cache_root: false,
            sampler: sampler_from(base),
            x_pending: pending,
            prune_baseline: false,
            incremental,
            ..Default::default()
        },
    )
    .unwrap()
}

#[test]
fn parity_log_noisy_expected_improvement() {
    let mut r = Report::default();
    for f in load() {
        let model = model_of(&f);
        let train_x = matrix(&f.train_x);
        for c in &f.nei {
            let baseline = match c.baseline.as_str() {
                "all" => train_x.clone(),
                "pruned" => {
                    let idx = &f.prune_baseline.indices;
                    Matrix::from_fn(idx.len(), train_x.ncols(), |i, j| train_x[(idx[i], j)])
                }
                other => panic!("unknown baseline {other}"),
            };
            let pending = c.x_pending.as_ref().map(|p| matrix(p));
            let acqf = nei(
                &model,
                &baseline,
                &c.base_samples,
                pending.clone(),
                c.incremental,
            );
            let x = matrix(&c.x);
            let (v, g) = acqf.forward_with_grad(&x).unwrap();
            // A second evaluation uses the cached incumbents.
            assert_eq!(acqf.forward(&x).unwrap(), v);
            let label = format!(
                "qLogNEI q={} pending={} inc={} baseline={}",
                c.q,
                pending.is_some(),
                c.incremental,
                c.baseline
            );
            r.check(
                &f.name,
                &format!("{label} value"),
                log_err(v, c.value),
                RTOL,
            );
            r.check(
                &f.name,
                &format!("{label} grad"),
                rel_err(&matrix_rows(&g), &flatten(&c.grad)),
                RTOL,
            );
        }
        // BoTorch's default cache_root=True with its effective base samples.
        let c = &f.nei_cache_root;
        let acqf = nei(&model, &train_x, &c.base_samples, None, true);
        let (v, g) = acqf.forward_with_grad(&matrix(&c.x)).unwrap();
        r.check(
            &f.name,
            "qLogNEI vs cache_root=True value",
            log_err(v, c.value_cache_root),
            RTOL,
        );
        r.check_slices_atol(
            &f.name,
            "qLogNEI vs cache_root=True grad",
            &matrix_rows(&g),
            &flatten(&c.grad_cache_root),
            RTOL,
            GRAD_ATOL,
        );
        r.check(
            &f.name,
            "qLogNEI vs cache_root=False value",
            log_err(v, c.value_plain),
            RTOL,
        );
    }
    r.finish("qLogNoisyExpectedImprovement");
}

#[test]
fn parity_prune_inferior_points() {
    for f in load() {
        let model = model_of(&f);
        let p = &f.prune;
        let z = matrix(&p.base_samples);
        let options = PruneOptions {
            num_samples: z.nrows(),
            base_samples: Some(z),
            ..Default::default()
        };
        let idx = prune_inferior_points_indices(model.as_ref(), &matrix(&p.x), &options).unwrap();
        assert_eq!(idx, p.indices, "{}: pruned indices", f.name);
        let zb = matrix(&f.prune_baseline.base_samples);
        let options = PruneOptions {
            num_samples: zb.nrows(),
            base_samples: Some(zb),
            ..Default::default()
        };
        let idx =
            prune_inferior_points_indices(model.as_ref(), &matrix(&f.train_x), &options).unwrap();
        assert_eq!(idx, f.prune_baseline.indices, "{}: pruned baseline", f.name);
        println!(
            "{:40} prune: {}/{} points kept (identical to BoTorch)",
            f.name,
            p.indices.len(),
            p.x.len()
        );
    }
}
